CREATE TABLE customers(id varchar(128) PRIMARY KEY, display_name varchar(255) NOT NULL, status varchar(16) NOT NULL DEFAULT 'ACTIVE',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts(id varchar(128) PRIMARY KEY,customer_id varchar(128) NOT NULL REFERENCES customers(id) ON DELETE RESTRICT,currency char(3) NOT NULL CHECK(currency='JOD'),available_balance numeric(19,3) NOT NULL CHECK(available_balance>=0),opening_balance numeric(19,3) NOT NULL CHECK(opening_balance>=0),status varchar(16) NOT NULL CHECK(status IN ('ACTIVE','FROZEN','CLOSED')),version bigint NOT NULL DEFAULT 0,receive_allowed boolean NOT NULL DEFAULT true,transfer_limit numeric(19,3) NOT NULL DEFAULT 10000.000,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE account_permissions(account_id varchar(128) REFERENCES accounts(id) ON DELETE RESTRICT,principal varchar(255),can_debit boolean NOT NULL DEFAULT false,can_receive boolean NOT NULL DEFAULT false,PRIMARY KEY(account_id,principal));
CREATE TABLE payments(payment_id uuid PRIMARY KEY,from_account_id varchar(128) NOT NULL,to_account_id varchar(128) NOT NULL,amount numeric(19,3) NOT NULL CHECK(amount>0),currency char(3) NOT NULL DEFAULT 'JOD',instruction_date timestamptz NOT NULL,purpose varchar(255) NOT NULL,notes varchar(1000),payload_fingerprint char(64) NOT NULL,status varchar(16) NOT NULL CHECK(status IN ('PENDING','COMPLETED','REJECTED')),rejection_code varchar(64),rejection_http integer,created_at timestamptz NOT NULL DEFAULT now(),processed_at timestamptz,requested_by varchar(255) NOT NULL,correlation_id uuid NOT NULL);
-- Account IDs deliberately have no FK on rejected instructions referring to absent accounts.
CREATE INDEX payments_from_time ON payments(from_account_id,created_at);
CREATE INDEX payments_to_time ON payments(to_account_id,created_at);
CREATE TABLE ledger_entries(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,payment_id uuid NOT NULL REFERENCES payments(payment_id) ON DELETE RESTRICT,account_id varchar(128) NOT NULL REFERENCES accounts(id) ON DELETE RESTRICT,entry_type varchar(8) NOT NULL CHECK(entry_type IN ('DEBIT','CREDIT')),signed_amount numeric(19,3) NOT NULL,balance_after numeric(19,3) NOT NULL CHECK(balance_after>=0),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(payment_id,entry_type),CHECK((entry_type='DEBIT' AND signed_amount<0) OR (entry_type='CREDIT' AND signed_amount>0)));
CREATE INDEX ledger_account ON ledger_entries(account_id);
CREATE FUNCTION immutable_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'financial record is immutable'; END $$;
CREATE TRIGGER immutable_ledger BEFORE UPDATE OR DELETE ON ledger_entries FOR EACH ROW EXECUTE FUNCTION immutable_record();
CREATE FUNCTION immutable_payment() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status<>'PENDING' OR TG_OP='DELETE' THEN RAISE EXCEPTION 'payment is immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER immutable_payments BEFORE UPDATE OR DELETE ON payments FOR EACH ROW EXECUTE FUNCTION immutable_payment();
CREATE FUNCTION verify_ledger() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE p uuid; s varchar; n bigint; a numeric; BEGIN p=COALESCE(NEW.payment_id,OLD.payment_id); SELECT status INTO s FROM payments WHERE payment_id=p; SELECT count(*),coalesce(sum(signed_amount),0) INTO n,a FROM ledger_entries WHERE payment_id=p; IF s='PENDING' OR (s='COMPLETED' AND (n<>2 OR a<>0)) OR (s='REJECTED' AND n<>0) THEN RAISE EXCEPTION 'unbalanced payment'; END IF; RETURN NULL; END $$;
CREATE CONSTRAINT TRIGGER payment_ledger_balance AFTER INSERT OR UPDATE ON payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verify_ledger();
CREATE CONSTRAINT TRIGGER ledger_balance AFTER INSERT ON ledger_entries DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION verify_ledger();
